int fun(start, end) {
    len = end - start + 1;

    if (len < 1 || end < 0 || start < 0)
        return 0;

    if (len % 3 == 0)
        return fun(start + 1, end);

    else if (len % 3 == 1)
        return 1 + fun(start, end - 1);

    else
        return fun(start + 2, end);
}

