#include <stdio.h>
int x = 180;   // global x

void func() {
    static int x = 10;   // static local x
    x += 5;
    printf("%d ", x);
}

int main() {
    int x = 1;          // local x (shadows global x)
    printf("%d ", x);   // (1)

    func();             
    {
        int x = 50;     // new local x (shadows outer x = 1)
        x++;
        printf("%d ", x);  

        func();     
    }

    printf("%d", x);    // (referring to in scope x , which is 2)
    return 0;
}

