void mystery(int a[ ],int n){
    int gap=n;
    bool red=true;
    while(gap!=1||red==true){
        gap=getNextGap(gap);
        red=false;
        for(int i=0;i<(n-gap);i++){
            if(a[i]>a[i+gap]){
                swap(a[i],a[i+gap]);
                red=true;
            }
        }
    }
}

int fun(int a[ ],int l, int target){
    int i=0,j=0,sum=0,count=0;
    while(j<l){
        if(sum<target){
            sum=sum+a[j];
            j++;
        }
        else if(sum>target){
            sum=sum-a[i];
            i++;
        }
        else{
            count++;
            sum=sum-a[i];
            i++;
        }
    }
    if(sum==target)
    count++;
    return count;
}

